INSERT INTO download_events (package_version_id, occurred_at)
SELECT
    package_versions.id,
    now() - (power(random(), 2.0) * interval '90 days')
FROM seed_downloads
JOIN package_versions ON package_versions.storage_key = seed_downloads.storage_key
CROSS JOIN LATERAL generate_series(1, seed_downloads.event_count)
WHERE NOT EXISTS (
    SELECT 1 FROM download_events
    WHERE download_events.package_version_id = package_versions.id
);

COMMIT;
